import{_ as a,o as s,c as o,ag as r}from"./chunks/framework.QfQ7DfGu.js";const h=JSON.parse('{"title":"龙芯实验室开源仓库","description":"","frontmatter":{"title":"龙芯实验室开源仓库","outline":"deep"},"headers":[],"relativePath":"repos/loongsonlab.md","filePath":"repos/loongsonlab.md"}'),l={name:"repos/loongsonlab.md"};function n(p,e,t,c,i,b){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="龙芯实验室开源仓库" tabindex="-1">龙芯实验室开源仓库 <a class="header-anchor" href="#龙芯实验室开源仓库" aria-label="Permalink to &quot;龙芯实验室开源仓库&quot;">​</a></h1><p>本页面收录龙芯实验室维护的两个 GitHub 仓库 <strong>Open-ChipHub</strong> 与 <strong>LoongsonLab</strong> 。</p><div class="past-loongson-topics-page repos-loongsonlab-page repos-lab"><section class="repos-lab-org" aria-labelledby="repos-lab-och-title"><header class="repos-lab-org__head"><h2 class="repos-lab-org__title" id="repos-lab-och-title">Open-ChipHub</h2><a class="repos-lab-org__cta" href="https://github.com/Open-ChipHub" target="_blank" rel="noopener noreferrer"> 浏览仓库 <span class="repos-lab-org__cta-arrow" aria-hidden="true">↗</span></a></header><p class="repos-lab-org__lede">侧重开放处理器平台、体系结构级模拟与验证、板级调试与配套 SDK 等基础设施。</p><div class="repos-lab-grid"><a class="repos-lab-tile" href="https://github.com/Open-ChipHub/LA_EMU" target="_blank" rel="noopener noreferrer"><span class="repos-lab-tile__name">LA_EMU</span><span class="repos-lab-tile__desc">LoongArch64 模拟器，支持整型，浮点，向量指令集；能够启动Linux, 运行大型测试</span></a><a class="repos-lab-tile" href="https://github.com/Open-ChipHub/LoongChipX" target="_blank" rel="noopener noreferrer"><span class="repos-lab-tile__name">异构多核处理器</span><span class="repos-lab-tile__desc">支持 LabCore364,LabCore164,LabCore132 以及后续开发中的六发射高性能处理器;平台提供仿真与验证功能，并配套 Linux 内核、GCC 与 LLVM 编译器等软件支持</span></a><a class="repos-lab-tile" href="https://github.com/Open-ChipHub/loong64-dv" target="_blank" rel="noopener noreferrer"><span class="repos-lab-tile__name">DV验证工具</span><span class="repos-lab-tile__desc">LA64架构的随机代码生成器，用于生成随机代码，作为处理器输入，与模拟器运行结果进行对比</span></a><a class="repos-lab-tile" href="https://github.com/Open-ChipHub/OpenOCD" target="_blank" rel="noopener noreferrer"><span class="repos-lab-tile__name">OpenOCD</span><span class="repos-lab-tile__desc">一款上板调试工具，已实现并支持 LoongChipX 平台</span></a><a class="repos-lab-tile" href="https://github.com/Open-ChipHub/LoongArch-SDK" target="_blank" rel="noopener noreferrer"><span class="repos-lab-tile__name">LoongArch-SDK</span><span class="repos-lab-tile__desc">提供了LoongArch架构下构建系统或软件所需要的开发工具包，包括:交叉编译工具,rootfs,,uefi固件等</span></a><a class="repos-lab-tile" href="https://github.com/Open-ChipHub/LoongChipX-doc" target="_blank" rel="noopener noreferrer"><span class="repos-lab-tile__name">LoongChipX-doc</span><span class="repos-lab-tile__desc">LoongChipX 平台的开放说明文档。</span></a></div></section><section class="repos-lab-org" aria-labelledby="repos-lab-lsl-title"><header class="repos-lab-org__head"><h2 class="repos-lab-org__title" id="repos-lab-lsl-title">LoongsonLab</h2><a class="repos-lab-org__cta" href="https://github.com/LoongsonLab" target="_blank" rel="noopener noreferrer"> 浏览仓库 <span class="repos-lab-org__cta-arrow" aria-hidden="true">↗</span></a></header><p class="repos-lab-org__lede">侧重教学操作系统、汇编级工具、RTOS，以及架构与内核交互类开放文档。</p><div class="repos-lab-grid"><a class="repos-lab-tile" href="https://github.com/LoongsonLab/LARS" target="_blank" rel="noopener noreferrer"><span class="repos-lab-tile__name">LARS</span><span class="repos-lab-tile__desc">龙芯汇编程序运行模拟器,支持LoongArch 32精简指令集;可实现汇编程序的编写、编译、运行、调试等功能，并提供如数据通路模拟、分支记录等拓展功能，供LoongArch汇编语言学习</span></a><a class="repos-lab-tile" href="https://github.com/LoongsonLab/StarryOS-LoongArch" target="_blank" rel="noopener noreferrer"><span class="repos-lab-tile__name">StarryOS-LoongArch</span><span class="repos-lab-tile__desc">基于ArceOS实现的宏内核</span></a><a class="repos-lab-tile" href="https://github.com/LoongsonLab/rt-thread" target="_blank" rel="noopener noreferrer"><span class="repos-lab-tile__name">RT-Thread</span><span class="repos-lab-tile__desc">开源的物联网端实时操作系统(RTOS)</span></a><a class="repos-lab-tile" href="https://github.com/LoongsonLab/OS_kernel_with_loong64_doc" target="_blank" rel="noopener noreferrer"><span class="repos-lab-tile__name">龙架构与OS交互文档</span><span class="repos-lab-tile__desc">LoongArch 与操作系统底层交互的开放文档说明</span></a></div></section></div>',3)])])}const g=a(l,[["render",n]]);export{h as __pageData,g as default};
